1	package main
2	
3	import (
4		"crypto/rand"
5		"encoding/hex"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"os"
10		"path/filepath"
11		"sort"
12		"strings"
13		"sync"
14		"time"
15	
16		// 内嵌时区数据库，保证在没有 /usr/share/zoneinfo 的环境中也能校验 IANA 时区。
17		_ "time/tzdata"
18	)
19	
20	// WeeklyHour 表示每周固定的一段开放时间。
21	// Weekday 用 1 到 7 表示周一至周日；Start/End 为 HH:mm。
22	// End 晚于 Start 表示当天结束，早于 Start 表示次日结束。
23	type WeeklyHour struct {
24		Weekday int    `json:"weekday"`
25		Start   string `json:"start"`
26		End     string `json:"end"`
27	}
28	
29	// Venue 是一条场地记录。
30	type Venue struct {
31		ID          string       `json:"id"`
32		Name        string       `json:"name"`
33		Capacity    int          `json:"capacity"`
34		Timezone    string       `json:"timezone"`
35		WeeklyHours []WeeklyHour `json:"weeklyHours"`
36	}
37	
38	// apiError 是返回给客户端的校验错误（HTTP 400）。
39	type apiError struct{ msg string }
40	
41	func (e *apiError) Error() string { return e.msg }
42	
43	func badRequest(format string, args ...any) error {
44		return &apiError{msg: fmt.Sprintf(format, args...)}
45	}
46	
47	// store 负责场地记录的持久化，所有访问都通过互斥锁串行化。
48	type store struct {
49		mu   sync.Mutex
50		path string
51	}
52	
53	func newStore(dataDir string) (*store, error) {
54		if err := os.MkdirAll(dataDir, 0700); err != nil {
55			return nil, err
56		}
57		path := filepath.Join(dataDir, "venues.json")
58		// 全新数据目录时初始化为空数组，保持原有行为。
59		file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
60		if err == nil {
61			if _, err := file.WriteString("[]\n"); err != nil {
62				_ = file.Close()
63				return nil, err
64			}
65			if err := file.Close(); err != nil {
66				return nil, err
67			}
68		} else if !errors.Is(err, os.ErrExist) {
69			return nil, err
70		}
71		return &store{path: path}, nil
72	}
73	
74	// load 读取并解析全部记录。读不到、JSON 损坏、结构异常或任一场地的
75	// 开放时段不合法都返回错误，调用方必须按 500 处理，绝不能把错误数据
76	// 当作空列表覆盖，也不能跳过异常场地只返回剩余记录。
77	func (s *store) load() ([]Venue, error) {
78		raw, err := os.ReadFile(s.path)
79		if err != nil {
80			return nil, err
81		}
82		var venues []Venue
83		if err := json.Unmarshal(raw, &venues); err != nil {
84			return nil, fmt.Errorf("venues data is corrupted: %w", err)
85		}
86		if venues == nil {
87			venues = []Venue{}
88		}
89		for i := range venues {
90			// 兼容旧数据：字段缺省或为 null 仍按空数组（暂未开放）读取。
91			if venues[i].WeeklyHours == nil {
92				venues[i].WeeklyHours = []WeeklyHour{}
93			}
94			// 已保存数据同样必须满足新增时的全部时段规则；任一非法即视为损坏。
95			if err := validateHours(venues[i].WeeklyHours); err != nil {
96				return nil, fmt.Errorf("venues data is corrupted: venue %q has invalid weekly hours: %w", venues[i].ID, err)
97			}
98		}
99		return venues, nil
100	}
101	
102	// save 通过同目录临时文件 + 重命名原子写入，避免半写状态损坏数据。
103	func (s *store) save(venues []Venue) error {
104		encoded, err := json.MarshalIndent(venues, "", "  ")
105		if err != nil {
106			return err
107		}
108		encoded = append(encoded, '\n')
109		dir := filepath.Dir(s.path)
110		tmp, err := os.CreateTemp(dir, ".venues-*.tmp")
111		if err != nil {
112			return err
113		}
114		tmpName := tmp.Name()
115		defer os.Remove(tmpName)
116		if _, err := tmp.Write(encoded); err != nil {
117			_ = tmp.Close()
118			return err
119		}
120		if err := tmp.Close(); err != nil {
121			return err
122		}
123		if err := os.Chmod(tmpName, 0600); err != nil {
124			return err
125		}
126		return os.Rename(tmpName, s.path)
127	}
128	
129	// list 返回当前全部场地（按首次创建顺序保留）。
130	func (s *store) list() ([]Venue, error) {
131		s.mu.Lock()
132		defer s.mu.Unlock()
133		return s.load()
134	}
135	
136	// create 校验请求内容，通过后写入新记录并返回保存后的场地。
137	// 校验失败时返回 apiError（400），不会写入任何内容。
138	func (s *store) create(payload map[string]any) (Venue, error) {
139		s.mu.Lock()
140		defer s.mu.Unlock()
141	
142		venues, err := s.load()
143		if err != nil {
144			return Venue{}, err
145		}
146	
147		venue, err := buildVenue(payload)
148		if err != nil {
149			return Venue{}, err
150		}
151	
152		venue.ID = newID()
153		for idTaken(venues, venue.ID) {
154			// 极小概率的随机碰撞：重新生成直到唯一。
155			venue.ID = newID()
156		}
157		venues = append(venues, venue)
158		if err := s.save(venues); err != nil {
159			return Venue{}, err
160		}
161		return venue, nil
162	}
163	
164	// buildVenue 对请求对象做逐字段严格校验。
165	func buildVenue(payload map[string]any) (Venue, error) {
166		name, err := requireString(payload, "name")
167		if err != nil {
168			return Venue{}, err
169		}
170		name = strings.TrimSpace(name)
171		if name == "" {
172			return Venue{}, badRequest("name 去除首尾空白后不能为空")
173		}
174	
175		capacity, err := requirePositiveInt(payload, "capacity")
176		if err != nil {
177			return Venue{}, err
178		}
179	
180		timezone, err := requireString(payload, "timezone")
181		if err != nil {
182			return Venue{}, err
183		}
184		if timezone == "" || timezone == "Local" {
185			return Venue{}, badRequest("timezone 必须是有效的 IANA 时区名称，例如 Asia/Shanghai")
186		}
187		if _, err := time.LoadLocation(timezone); err != nil {
188			return Venue{}, badRequest("timezone 必须是有效的 IANA 时区名称，例如 Asia/Shanghai")
189		}
190	
191		rawHours, ok := payload["weeklyHours"]
192		if !ok {
193			return Venue{}, badRequest("缺少 weeklyHours 字段")
194		}
195		hours, err := parseWeeklyHours(rawHours)
196		if err != nil {
197			return Venue{}, err
198		}
199		if err := validateHours(hours); err != nil {
200			// 读取已保存数据时 validateHours 的错误按数据损坏（500）处理；
201			// 这里是新增请求，包装成面向客户端的 400 校验错误。
202			return Venue{}, badRequest("%s", err.Error())
203		}
204	
205		return Venue{
206			Name:        name,
207			Capacity:    capacity,
208			Timezone:    timezone,
209			WeeklyHours: hours,
210		}, nil
211	}
212	
213	func missingOrWrong(field, kind string) error {
214		return badRequest("%s 类型错误：应为%s", field, kind)
215	}
216	
217	func requireString(payload map[string]any, field string) (string, error) {
218		value, ok := payload[field]
219		if !ok || value == nil {
220			return "", missingOrWrong(field, "字符串")
221		}
222		str, ok := value.(string)
223		if !ok {
224			return "", missingOrWrong(field, "字符串")
225		}
226		return str, nil
227	}
228	
229	// jsonInt 取出一个 JSON 数字并要求它是整数；正数范围由调用方决定。
230	func jsonInt(value any) (int, bool) {
231		number, ok := value.(float64)
232		if !ok {
233			return 0, false
234		}
235		if number != float64(int64(number)) {
236			return 0, false
237		}
238		return int(number), true
239	}
240	
241	func requirePositiveInt(payload map[string]any, field string) (int, error) {
242		value, ok := payload[field]
243		if !ok || value == nil {
244			return 0, missingOrWrong(field, "正整数")
245		}
246		number, ok := jsonInt(value)
247		if !ok || number <= 0 {
248			return 0, missingOrWrong(field, "正整数")
249		}
250		return number, nil
251	}
252	
253	func parseWeeklyHours(raw any) ([]WeeklyHour, error) {
254		if raw == nil {
255			return nil, badRequest("weeklyHours 类型错误：应为数组")
256		}
257		items, ok := raw.([]any)
258		if !ok {
259			return nil, badRequest("weeklyHours 类型错误：应为数组")
260		}
261		hours := make([]WeeklyHour, 0, len(items))
262		for i, item := range items {
263			obj, ok := item.(map[string]any)
264			if !ok || obj == nil {
265				return nil, badRequest("weeklyHours[%d] 类型错误：应为对象", i)
266			}
267			rawWeekday, ok := obj["weekday"]
268			if !ok || rawWeekday == nil {
269				return nil, badRequest("weeklyHours[%d].weekday 类型错误：应为 1 到 7 的整数", i)
270			}
271			weekday, ok := jsonInt(rawWeekday)
272			if !ok {
273				return nil, badRequest("weeklyHours[%d].weekday 类型错误：应为 1 到 7 的整数", i)
274			}
275			if weekday < 1 || weekday > 7 {
276				return nil, badRequest("weeklyHours[%d].weekday 必须为 1 到 7（周一至周日）", i)
277			}
278			start, err := hourField(obj, i, "start")
279			if err != nil {
280				return nil, err
281			}
282			end, err := hourField(obj, i, "end")
283			if err != nil {
284				return nil, err
285			}
286			hours = append(hours, WeeklyHour{Weekday: weekday, Start: start, End: end})
287		}
288		return hours, nil
289	}
290	
291	func hourField(obj map[string]any, i int, field string) (string, error) {
292		value, ok := obj[field]
293		if !ok || value == nil {
294			return "", badRequest("weeklyHours[%d].%s 类型错误：应为 HH:mm 时间", i, field)
295		}
296		str, ok := value.(string)
297		if !ok || !validHHMM(str) {
298			return "", badRequest("weeklyHours[%d].%s 时间无效，必须为 00:00 至 23:59 的 HH:mm 格式", i, field)
299		}
300		return str, nil
301	}
302	
303	// validHHMM 严格校验 HH:mm：两位小时、冒号、两位分钟，范围 00:00–23:59。
304	func validHHMM(value string) bool {
305		if len(value) != 5 || value[2] != ':' {
306			return false
307		}
308		for i, c := range value {
309			if i == 2 {
310				continue
311			}
312			if c < '0' || c > '9' {
313				return false
314			}
315		}
316		hour := int(value[0]-'0')*10 + int(value[1]-'0')
317		minute := int(value[3]-'0')*10 + int(value[4]-'0')
318		return hour <= 23 && minute <= 59
319	}
320	
321	func minutes(value string) int {
322		return int(value[0]-'0')*600 + int(value[1]-'0')*60 +
323			int(value[3]-'0')*10 + int(value[4]-'0')
324	}
325	
326	// interval 是展开到周时间轴上的一段开放时间，单位为分钟。
327	// 周一 00:00 为起点 0。
328	type interval struct {
329		start int
330		end   int
331		label string
332	}
333	
334	// validateHours 按开放时段的业务规则检查一段已解析的时段数据。
335	// 规则同时用于新增请求（400 校验）和已保存数据（损坏时按 500 处理）：
336	// 星期为 1–7（周一至周日），时间为严格 HH:mm（00:00–23:59），
337	// 起止时间不能相同；结束早于开始表示次日结束。重叠判断覆盖跨午夜
338	// 延续到次日的部分，也包含周日延续到下周一的部分；部分重叠、完全
339	// 包含和重复时段都不合法，下一段恰好在前一段结束时开始合法。
340	// 时段的填写顺序不影响结果。
341	//
342	// 返回的是普通错误而非 apiError：读取已保存数据命中时按数据损坏（500）
343	// 处理；新增流程由 buildVenue 包装成面向客户端的 400 错误。
344	func validateHours(hours []WeeklyHour) error {
345		intervals := make([]interval, 0, len(hours)*2)
346		for _, h := range hours {
347			if h.Weekday < 1 || h.Weekday > 7 {
348				return fmt.Errorf("开放时段无效：星期 %d 不在 1 到 7（周一至周日）范围内", h.Weekday)
349			}
350			if !validHHMM(h.Start) || !validHHMM(h.End) {
351				return fmt.Errorf("开放时段无效：%s 的时间 %s-%s 不是合法的 HH:mm", weekdayName(h.Weekday), h.Start, h.End)
352			}
353			startMin := minutes(h.Start)
354			endMin := minutes(h.End)
355			label := fmt.Sprintf("%s %s-%s", weekdayName(h.Weekday), h.Start, h.End)
356			if startMin == endMin {
357				return fmt.Errorf("开放时段无效：%s 的结束时间与开始时间相同", label)
358			}
359			start := (h.Weekday-1)*1440 + startMin
360			end := (h.Weekday-1)*1440 + endMin
361			if endMin < startMin {
362				end += 1440 // 跨午夜，次日结束
363			}
364			intervals = append(intervals, interval{start: start, end: end, label: label})
365		}
366		// 复制到下一周，用于检测周日跨午夜与下周一时段相交。
367		base := make([]interval, len(intervals))
368		copy(base, intervals)
369		for _, iv := range base {
370			intervals = append(intervals, interval{
371				start: iv.start + 7*1440,
372				end:   iv.end + 7*1440,
373				label: iv.label,
374			})
375		}
376		sort.Slice(intervals, func(i, j int) bool {
377			if intervals[i].start != intervals[j].start {
378				return intervals[i].start < intervals[j].start
379			}
380			return intervals[i].end < intervals[j].end
381		})
382		for i := 1; i < len(intervals); i++ {
383			if intervals[i].start < intervals[i-1].end {
384				return fmt.Errorf("开放时段存在相交：%s 与其他时段重叠", intervals[i].label)
385			}
386		}
387		return nil
388	}
389	
390	func weekdayName(weekday int) string {
391		return [...]string{"", "周一", "周二", "周三", "周四", "周五", "周六", "周日"}[weekday]
392	}
393	
394	// newID 生成非空、概率上唯一的记录标识。
395	func newID() string {
396		b := make([]byte, 16)
397		if _, err := rand.Read(b); err != nil {
398			// crypto/rand 失败极不寻常；退化为纳秒时间戳，仍保证非空且基本唯一。
399			return fmt.Sprintf("v-%d", time.Now().UnixNano())
400		}
401		return hex.EncodeToString(b)
402	}
403	
404	func idTaken(venues []Venue, id string) bool {
405		for _, v := range venues {
406			if v.ID == id {
407				return true
408			}
409		}
410		return false
411	}
